    productDetails: "{\"form\":\"خوذة LED مع تدليك وتسخين\",\"patent\":\"براءة اختراع رقم 10-2151442\",\"award\":\"الميدالية البرونزية - مسابقة براءات الاختراع الكورية 2020\",\"target\":\"علاج تساقط الشعر وتعزيز النمو\",\"technology\":\"LED (تحت أحمر + أحمر + أزرق) + ضغط الهواء + تسخين\",\"keyBenefits\":\"تحسين الدورة الدموية، تغذية البصيلات، تخفيف التوتر\",\"usage\":\"احترافي ومنزلي\",\"skinType\":\"جميع أنواع فروة الرأس\",\"size\":\"جهاز واحد\",\"features\":\"تدليك، تسخين، وضع الموسيقى\",\"origin\":\"كوريا الجنوبية\"}",
